__author__ = 'keskimol'

import re
import xml.etree.ElementTree as etree
from hran_elementmanager2g.utils.loggers import logger

class XMLParser(object):
    ENCODING = "ISO-8859-1"

    """
    Custom parser that uses built-in Python ElementTree parser.
    """

    def __init__(self, xml_file_in, xml_out=""):
        """
        Default constructor
        :param xml_file_in:
        :param xml_out:
        :return:
        """
        self.xml_file_in = xml_file_in
        self.xml_out = xml_out if xml_out else xml_file_in
        self.tree = None
        self.root = self._parse_xml_with_comments(self.xml_file_in)
        self._etree_register_namespace()

    def _parse_xml_with_comments(self, filename):
        """
        Parse xml by using commented tree builder utility
        :param filename:
        :return:
        """
        try:
            with open(filename, 'r') as f:
                self.tree = etree.parse(f)
            return self.tree.getroot()  # root element instance
        except etree.ParseError:
            raise etree.ParseError("cElementTree is unable to parse file '%s'" % filename)
        except IOError:
            raise

    def save_xml(self):
        """
        Saves class xml-tree
        :return:
        """
        self.tree.write(self.xml_out, encoding=self.ENCODING)

    def update_root_attrib_with_value(self, attrib, value):
        """
        Update root attribute value with new value
        :param attrib:
        :param value:
        :return:
        """
        for child in self.root:
            old_val = child.get(attrib)
            if old_val != value:
                child.set(attrib, value)
                logger.debug("Updated root: %s : %s (was: %s)" % (attrib, value, old_val))

    def update_childobj_attrib_with_value(self, object_name, attrib, value):
        for child in self.root:
            for child2 in child:
                if child2.tag.find(object_name) != -1:
                    old_val = child2.get(attrib)
                    if old_val != "create":
                        child2.set(attrib, value)
                        logger.debug("Updated object %s: %s : %s (was: %s)" % (object_name, attrib, value, old_val))

    def print_values_for_attrib(self, attrib):
        """
        Print all root values for attribute
        :param attrib:
        :return:
        """
        for child in self.root.findall(attrib):
            print(child.get(attrib), child.find(attrib).text)

    def get_root(self):
        """
        Return xml root
        :return:
        """
        return self.root

    def _etree_register_namespace(self):
        """
        Register the new xml tree namespace with the original namespace (required for consistency in writing)
        :return:
        """
        m = re.search("{.*}", self.root.tag)
        xmlns = m.group(0).lstrip("{").rstrip("}")
        etree.register_namespace("", xmlns)

    def update_gsm_scf(self):
        """
        Runner.
        :return:
        """
        logger.info("Updating XML attributes...")
        self.update_root_attrib_with_value("scope", "all")
        self.update_root_attrib_with_value("type", "plan")
        self.update_childobj_attrib_with_value("managedObject", "operation", "create")
        logger.info("Updated finished.")
        self.save_xml()
        logger.info("XML saved '%s'" % self.xml_out)
